#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        long long sum = 0, x;
        int count = 0;
        while (in >> x) {
            sum += x;
            count++;
        }
        if (count == 0) {
            std::cout << "пусто\n";
        } else {
            std::cout << sum << '\n';
        }
    }
    return 0;
}

