#include <iostream>
#include <string>

int main() {
    long long sum = 0;
    int numbers = 0, skipped = 0;
    while (true) {
        int x;
        if (std::cin >> x) {
            sum += x;
            numbers++;
        } else if (std::cin.eof()) {
            break;
        } else {
            std::cin.clear();
            std::string bad;
            std::cin >> bad;
            skipped++;
        }
    }
    std::cout << "сумма " << sum << ", чисел " << numbers << ", пропущено " << skipped << '\n';
    return 0;
}

